def findAllocationWays(p1, q1, p2, q2):
    MOD = 998244353
    R, C = p2 - p1 + 1, q2 - q1 + 1
    dp = [[0] * C for _ in range(R)]
    dp[0][0] = 1
    for a in range(R):
        for b in range(C):
            if a == 0 and b == 0:
                continue
            i, j = p1 + a, q1 + b  # actual rows / columns
            v = 0
            if a > 0:
                v += dp[a - 1][b] * j
            if b > 0:
                v += dp[a][b - 1] * i
            if a > 0 and b > 0:
                v -= dp[a - 1][b - 1] * (i - 1) * (j - 1)
            dp[a][b] = v % MOD
    return dp[R - 1][C - 1]

class Solution {
    public int findAllocationWays(int p1, int q1, int p2, int q2) {
        final long MOD = 998244353L;
        int R = p2 - p1 + 1, C = q2 - q1 + 1;
        long[][] dp = new long[R][C];
        dp[0][0] = 1;
        for (int i = 0; i < R; i++) {
            for (int j = 0; j < C; j++) {
                if (i == 0 && j == 0) continue;
                long v = 0;
                if (i > 0) v += dp[i - 1][j] * (q1 + j);
                if (j > 0) v += dp[i][j - 1] * (p1 + i);
                if (i > 0 && j > 0) v -= dp[i - 1][j - 1] * (p1 + i - 1) % MOD * (q1 + j - 1) % MOD;
                dp[i][j] = ((v % MOD) + MOD) % MOD;
            }
        }
        return (int) dp[R - 1][C - 1];
    }
}

